package io.github.long0823.tclviewer;
import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import org.json.*;import com.caverock.androidsvg.SVG;
final class StationLogos implements AutoCloseable {
 private final Context context;private final File cache;private final Handler ui=new Handler(Looper.getMainLooper());private final ExecutorService workers=Executors.newFixedThreadPool(2);private final Map<String,String> urls=new HashMap<>();private final ConcurrentHashMap<String,Bitmap> images=new ConcurrentHashMap<>();private final ConcurrentHashMap<String,Long> failures=new ConcurrentHashMap<>();private final ConcurrentHashMap<String,ArrayList<LogoView>> pending=new ConcurrentHashMap<>();private volatile boolean closed;
 StationLogos(Context c){context=c;cache=new File(c.getCacheDir(),"station-logos");cache.mkdirs();try{JSONArray array=new JSONArray(new String(MainActivity.read(c.getAssets().open("station_logos.json"),65536),java.nio.charset.StandardCharsets.UTF_8));for(int i=0;i<array.length();i++){JSONObject item=array.getJSONObject(i);urls.put(item.getString("key"),item.getString("url"));}}catch(Exception ignored){}}
 private int dp(int x){return (int)(x*context.getResources().getDisplayMetrics().density+.5f);}
 private android.graphics.drawable.GradientDrawable shape(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private final class LogoView extends FrameLayout {final ImageView image;final TextView fallback;LogoView(String name,int size){super(context);setBackground(shape(0xffffffff,12));setClipToOutline(true);fallback=new TextView(context);fallback.setText(StationIdentity.initials(name));fallback.setTextSize(size>=44?15:11);fallback.setTypeface(null,1);fallback.setGravity(Gravity.CENTER);fallback.setTextColor(0xff334766);addView(fallback,new LayoutParams(-1,-1));image=new ImageView(context);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setPadding(dp(4),dp(4),dp(4),dp(4));addView(image,new LayoutParams(-1,-1));setContentDescription(name+"の局ロゴ");}void display(Bitmap bitmap){if(bitmap==null)return;int samples=0,light=0,transparent=0;for(int y=0;y<bitmap.getHeight();y+=8)for(int x=0;x<bitmap.getWidth();x+=8){int p=bitmap.getPixel(x,y);if(Color.alpha(p)<40){transparent++;continue;}samples++;if(Color.red(p)>220&&Color.green(p)>220&&Color.blue(p)>220)light++;}setBackground(shape(samples>0&&light>samples*.95&&transparent>0?0xff17202a:0xffffffff,12));image.setImageBitmap(bitmap);fallback.setVisibility(GONE);}}
 View view(ChannelConfig.Channel channel,List<ChannelConfig.Channel> channels,int size){LogoView view=new LogoView(channel.name,size);String key=StationIdentity.key(channel,channels);if(key.isEmpty()||!urls.containsKey(key)||closed)return view;Bitmap bitmap=images.get(key);if(bitmap!=null){view.display(bitmap);return view;}Long failed=failures.get(key);if(failed!=null&&System.currentTimeMillis()-failed<60000)return view;ArrayList<LogoView> list=pending.get(key);if(list!=null){list.add(view);return view;}list=new ArrayList<>();list.add(view);pending.put(key,list);try{workers.execute(()->{Bitmap loaded=null;try{File file=new File(cache,key+"-"+Integer.toHexString(urls.get(key).hashCode())+".png");if(file.isFile())loaded=BitmapFactory.decodeFile(file.getAbsolutePath());if(loaded==null){byte[] bytes=download(urls.get(key));String head=new String(bytes,0,Math.min(256,bytes.length),java.nio.charset.StandardCharsets.UTF_8);if(bytes.length>6&&bytes[0]==0&&bytes[1]==0&&bytes[2]==1&&bytes[3]==0){loaded=decodeIco(bytes);}else if(head.contains("<svg")||head.startsWith("<?xml")){SVG svg=SVG.getFromInputStream(new ByteArrayInputStream(bytes));Picture picture=svg.renderToPicture();float ratio=(float)picture.getWidth()/Math.max(1,picture.getHeight());int w=192,h=Math.max(1,(int)(192/Math.max(.05f,ratio)));if(h>192){h=192;w=Math.max(1,(int)(192*ratio));}loaded=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(loaded);canvas.drawPicture(picture,new Rect(0,0,w,h));}else{BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);if(bounds.outWidth<1||bounds.outHeight<1||bounds.outWidth>4096||bounds.outHeight>4096)throw new IOException();BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=Math.max(1,Math.max(bounds.outWidth,bounds.outHeight)/256);loaded=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);}if(loaded==null)throw new IOException();try(OutputStream out=new FileOutputStream(file)){loaded.compress(Bitmap.CompressFormat.PNG,100,out);}}images.put(key,loaded);}catch(Exception e){android.util.Log.w("StationLogos","Logo unavailable: "+key,e);failures.put(key,System.currentTimeMillis());}final Bitmap result=loaded;ui.post(()->{ArrayList<LogoView> targets=pending.remove(key);if(closed||targets==null)return;for(LogoView target:targets)target.display(result);});});}catch(RejectedExecutionException ignored){}return view;}
 private static int le16(byte[] b,int p){return (b[p]&255)|((b[p+1]&255)<<8);}private static int le32(byte[] b,int p){return le16(b,p)|(le16(b,p+2)<<16);}
 private static Bitmap decodeIco(byte[] b)throws IOException {int count=Math.min(64,le16(b,4));ArrayList<Integer> entries=new ArrayList<>();for(int n=0;n<count&&6+(n+1)*16<=b.length;n++)entries.add(6+n*16);entries.sort((a,c)->Integer.compare(((b[c]&255)==0?256:b[c]&255),((b[a]&255)==0?256:b[a]&255)));for(int entry:entries)try{int size=le32(b,entry+8),off=le32(b,entry+12);if(off<0||size<40||off>b.length-size)continue;if((b[off]&255)==137&&b[off+1]==80){BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(b,off,size,bounds);if(bounds.outWidth>0&&bounds.outWidth<=512&&bounds.outHeight>0&&bounds.outHeight<=512)return BitmapFactory.decodeByteArray(b,off,size);continue;}int header=le32(b,off),w=le32(b,off+4),h=le32(b,off+8)/2,bits=le16(b,off+14);if(header<40||w<1||h<1||w>512||h>512||le32(b,off+16)!=0||(bits!=1&&bits!=4&&bits!=8&&bits!=24&&bits!=32))continue;int colors=bits<=8?le32(b,off+32):0;if(bits<=8&&colors==0)colors=1<<bits;int pixels=off+header+colors*4,stride=((w*bits+31)/32)*4,mask=pixels+stride*h,maskStride=((w+31)/32)*4;if(pixels<off||mask>off+size)continue;boolean alpha=false;if(bits==32)for(int n=0;n<w*h;n++)if((b[pixels+(n/w)*stride+(n%w)*4+3]&255)!=0){alpha=true;break;}int[] out=new int[w*h];for(int y=0;y<h;y++)for(int x=0;x<w;x++){int row=h-1-y,p=pixels+row*stride,rgb,a=255;if(bits==32||bits==24){p+=x*(bits/8);rgb=((b[p+2]&255)<<16)|((b[p+1]&255)<<8)|(b[p]&255);if(bits==32&&alpha)a=b[p+3]&255;}else{int index=bits==8?b[p+x]&255:bits==4?((b[p+x/2]&255)>>(x%2==0?4:0))&15:((b[p+x/8]&255)>>(7-x%8))&1;if(index>=colors)throw new IOException();p=off+header+index*4;rgb=((b[p+2]&255)<<16)|((b[p+1]&255)<<8)|(b[p]&255);}if(mask+(row+1)*maskStride<=off+size&&((b[mask+row*maskStride+x/8]>>(7-x%8))&1)!=0)a=0;out[y*w+x]=(a<<24)|rgb;}return Bitmap.createBitmap(out,w,h,Bitmap.Config.ARGB_8888);}catch(Exception ignored){}throw new IOException("Unsupported site icon");}
 private static byte[] download(String value)throws IOException{for(int attempt=0;attempt<4;attempt++){URL url=new URL(value);if(!url.getProtocol().equals("https"))throw new IOException();HttpURLConnection c=(HttpURLConnection)url.openConnection();try{c.setConnectTimeout(5000);c.setReadTimeout(6000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","TCLViewer/0.3 station-logo");int status=c.getResponseCode();if(status>=300&&status<400){value=new URL(url,c.getHeaderField("Location")).toString();continue;}if(status!=200)throw new IOException();return MainActivity.read(c.getInputStream(),1048576);}finally{c.disconnect();}}throw new IOException();}
 void retry(){failures.clear();images.clear();File[] files=cache.listFiles();if(files!=null)for(File file:files)if(file.getName().endsWith(".png"))file.delete();}
 public void close(){closed=true;workers.shutdownNow();ui.removeCallbacksAndMessages(null);pending.clear();}
}